        assistOpen:false,assistBusy:false,assistQuote:null,assistCoins:null,assistBalance:null,assistOperation:'review',assistMinds:[],assistConstraints:'',assistProposal:null,assistSelected:[],assistError:'',assistSequence:0,
        assistBody(){return{operation:this.assistOperation,payload:this.p,mind_ids:this.assistMinds,constraints:this.assistConstraints,quote:this.assistQuote};},
        resetAssist(){++this.assistSequence;this.assistQuote=null;this.assistCoins=null;},
        async estimateAssist(){this.assistBusy=true;this.assistError='';this.assistProposal=null;const seq=++this.assistSequence;try{const j=await this.forecastRequest(@js(route('user.marketing-plan.assist.estimate')),'POST',this.assistBody());if(seq!==this.assistSequence)return;this.assistCoins=j.coins;this.assistBalance=j.balance;this.assistQuote=j.quote;}catch(e){this.assistError=e.message;}finally{this.assistBusy=false;}},
        async generateAssist(){this.assistBusy=true;this.assistError='';try{this.assistProposal=await this.forecastRequest(@js(route('user.marketing-plan.assist.generate')),'POST',this.assistBody());this.assistSelected=Object.keys(this.assistProposal.suggestions);this.assistQuote=null;}catch(e){this.assistError=e.message;this.resetAssist();}finally{this.assistBusy=false;}},
        applyAssist(){for(const key of this.assistSelected){if(key==='channels'){for(const row of this.assistProposal.suggestions.channels||[]){const c=this.p.channels.find(c=>c.key===row.key);if(c)Object.assign(c,row);}}else this.p[key]=this.assistProposal.suggestions[key];}this.recordOrigins(this.assistSelected,'AI suggested');this.assistProposal=null;this.savedFlash=false;this.resetAssist();},
